  function openTaskForm(){syncState();if(!window.RoleAccessAdminV4?.can('settings'))return toast('Sem autorização para configurar tarefas.');modal('Nova tarefa',`<div class="form-grid"><div class="span-2"><label>Nome</label><input id="tName"></div><div><label>Fase</label><select id="tPhase"><option value="open">Abertura</option><option value="live">Durante o dia</option><option value="close">Fecho</option></select></div><div><label>Obrigatória</label><select id="tRequired"><option value="1">Sim</option><option value="0">Não</option></select></div><div><label>Clínica</label><select id="tClinic"><option value="all">Todas</option>${options(liveClinics(),x=>x.id,x=>x.name)}</select></div><div><label>Responsável / perfil</label><input id="tRole" value="Administrativa"></div><div><label>Periodicidade</label><select id="tFrequency"><option>Diária</option><option>Semanal</option><option>Mensal</option><option>Pontual</option></select></div><div><label>Hora limite</label><input id="tDeadline" type="time" value="17:00"></div><div><label>Tipo de resposta</label><select id="tResponse"><option>sim/não</option><option>número</option><option>texto</option><option>checklist</option><option>seleção de médico/técnico</option></select></div><div><label>Ação / módulo associado</label><select id="tAction"><option value="none">Sem ação</option><option value="planning">Planning</option><option value="wait">Pedidos</option><option value="confirm">Confirmações</option><option value="reval">Reavaliações</option><option value="hr">RH</option></select></div></div><button class="primary" style="margin-top:14px" onclick="App.addTask()">Criar tarefa</button>`)}
  function addTask(){syncState();if(!window.RoleAccessAdminV4?.can('settings'))return toast('Sem autorização para configurar tarefas.');const name=$('tName').value.trim();if(!name)return toast('Nome obrigatório');const t={id:uid('task'),name,phase:$('tPhase').value,required:$('tRequired').value==='1',clinics:[$('tClinic').value],role:$('tRole').value,frequency:$('tFrequency').value,deadline:$('tDeadline').value,response:$('tResponse').value,action:$('tAction').value,active:true};state.tasks.push(t);audit('Configuração','Tarefa criada',t.name);persist();closeModal()}
